5	namespace App\Filament\Resources\Products\Pages;
6	
7	use App\Filament\Resources\Category2s\Category2Resource;
8	use App\Filament\Resources\Products\ProductResource;
9	use App\Models\Category2;
10	use AtrioTeam\DigitalHub\Filament\Concerns\IsDigitalHubListPage;
11	use Filament\Resources\Pages\ListRecords;
12	use Illuminate\Database\Eloquent\Builder;
13	use Illuminate\Database\Eloquent\Relations\Relation;
14	use Override;
