16	class ListProducts extends ListRecords
17	{
18	    use IsDigitalHubListPage;
19	
20	    protected static string $resource = ProductResource::class;
21	
22	    /**
23	     * @return Builder<\Illuminate\Database\Eloquent\Model>|Relation<\Illuminate\Database\Eloquent\Model, \Illuminate\Database\Eloquent\Model, *>|null
24	     */
25	    #[Override]
26	    protected function getTableQuery(): Builder|Relation|null
27	    {
28	        $query = parent::getTableQuery();
29	        $category2Id = request()->query('category_2');
30	
31	        if ($query !== null && is_string($category2Id) && $category2Id !== '') {
32	            $query->where('category_2_id', (int) $category2Id);
33	        }
34	
35	        return $query;
36	    }
37	
38	    /** @return array<string|int, string> */
39	    #[Override]
40	    public function getBreadcrumbs(): array
41	    {
42	        $category2Id = request()->query('category_2');
43	        if (! is_string($category2Id) || $category2Id === '') {
44	            return parent::getBreadcrumbs();
45	        }
46	
47	        $category2 = Category2::query()->with('category1')->find((int) $category2Id);
48	        if ($category2 === null) {
49	            return parent::getBreadcrumbs();
50	        }
51	
52	        $crumbs = [];
53	
54	        if ($category2->category1 !== null) {
55	            $crumbs[Category2Resource::getUrl('index', ['category_1' => $category2->category1->id])] = $category2->category1->name;
56	        }
57	
58	        $crumbs['#'] = $category2->name;
59	        $crumbs[] = __('product.model_plural');
60	
61	        return $crumbs;
62	    }
63	
64	
65	}
