3	declare(strict_types=1);
4	
5	namespace App\Models;
6	
7	use App\Concerns\LogsCatalogActivity;
8	use AtrioTeam\DigitalHub\Assets\Concerns\HasAssets;
9	use AtrioTeam\DigitalHub\Assets\Contracts\OwnsAssets;
10	use AtrioTeam\DigitalHub\Identity\Concerns\HasGlobalId;
11	use AtrioTeam\DigitalHub\Pim\AttributeSchema;
12	use AtrioTeam\DigitalHub\Pim\Concerns\HasTechnicalAttributes;
13	use AtrioTeam\DigitalHub\Tags\Models\Tag;
14	use Illuminate\Database\Eloquent\Model;
15	use Illuminate\Database\Eloquent\Relations\BelongsTo;
16	use Illuminate\Database\Eloquent\Relations\BelongsToMany;
17	use Illuminate\Database\Eloquent\Relations\HasMany;
18	use Illuminate\Database\Eloquent\SoftDeletes;
19	use InvalidArgumentException;
20	use Laravel\Scout\Searchable;
21	use Spatie\MediaLibrary\HasMedia;
22	use Spatie\Tags\HasTags;
23	use Spatie\Translatable\Attributes\Translatable;
24	use Spatie\Translatable\HasTranslations;
25	
26	#[Translatable('name')]
27	class Product extends Model implements HasMedia, OwnsAssets
28	{
29	    use HasAssets;
30	    use HasGlobalId;
31	    use HasTags;
32	    use HasTechnicalAttributes;
33	    use HasTranslations;
34	    use LogsCatalogActivity;
35	    use Searchable;
36	    use SoftDeletes;
37	
38	    /**
39	     * Colonna riempita dal trait con l'ultimo utente che ha salvato.
40	     */
41	    protected static ?string $updatedByColumn = 'updated_by';
42	
43	    protected $guarded = [];
44	
45	    /**
46	     * Colonne reali su cui il driver "database" di Scout costruisce le
47	     * LIKE (roadmap #23): le chiavi devono corrispondere a colonne della
48	     * tabella, non a valori arbitrari. `name_search` è una colonna generata
49	     * STORED (cast a testo di `name`, JSON translatable): MySQL confronta il
50	     * JSON grezzo con LIKE usando collation binaria (case-sensitive) a
51	     * prescindere dalla collation di connessione, il cast la aggira. Match
52	     * grezzo su tutte le lingue incluso.
