10	/**
11	 * Schema base di attributi PIM per un'entità.
12	 *
13	 * Sottoclassi dichiarano gli attributi e (opzionalmente) i raggruppamenti
14	 * per la UI. Lo schema è la fonte di verità per validazione, locale-aware
15	 * reads e generazione del form Filament.
16	 */
17	abstract class AttributeSchema
18	{
19	    /**
20	     * Mappa nome-attributo → Type.
21	     *
22	     * @return array<string, TypeBuilder>
23	     */
24	    abstract public function attributes(): array;
25	
26	    /**
27	     * Raggruppamenti per la UI (Tabs). Default: un unico gruppo con tutto.
28	     *
29	     * @return array<string, list<string>>
30	     */
31	    public function groups(): array
32	    {
33	        return ['default' => array_keys($this->attributes())];
34	    }
35	
36	    public function getType(string $key): ?TypeBuilder
37	    {
38	        return $this->attributes()[$key] ?? null;
39	    }
40	
41	    /** @return array<string, TypeBuilder> */
42	    public function getFilterableAttributes(): array
43	    {
44	        return array_filter($this->attributes(), static fn (TypeBuilder $t) => $t->isFilterable());
45	    }
46	
47	    /**
48	     * Regole di validazione Laravel per ogni attributo dello schema.
49	     *
50	     * Riceve il modello perché la regola `unique` opera sul path JSON della
51	     * colonna attributi (es. `attributes->sku`) e, in update, deve ignorare la
52	     * riga corrente: tabella, colonna e PK sono noti solo al modello, non al
53	     * TypeBuilder. Le altre regole derivano dai modificatori del tipo.
54	     *
55	     * @param Model $model istanza che usa il trait HasTechnicalAttributes
56	     * @return array<string, list<mixed>>
57	     */
58	    public function validationRules(Model $model): array
59	    {
60	        /** @var string $column */
61	        // @phpstan-ignore method.notFound (HasTechnicalAttributes trait)
62	        $column = $model->attributesColumn();
63	        $table = $model->getTable();
64	
65	        $rules = [];
66	        foreach ($this->attributes() as $key => $type) {
67	            $attrRules = $type->toValidationRules();
68	
69	            if ($type->isUnique()) {
70	                $rule = Rule::unique($table, "{$column}->{$key}");
71	                if ($model->exists) {
72	                    $rule->ignore($model);
73	                }
74	                $attrRules[] = $rule;
75	            }
76	
77	            $rules[$key] = $attrRules;
78	        }
79	
80	        return $rules;
81	    }
82	}
