5	namespace App\Filament\Resources\Products\Actions;
6	
7	use App\Models\Category1;
8	use App\Models\Product;
9	use AtrioTeam\DigitalHub\Pim\Enum\Type;
10	use Filament\Actions\Action;
11	use Filament\Forms\Components\Select;
12	use Filament\Support\Icons\Heroicon;
13	use Illuminate\Database\Eloquent\Collection;
14	use Illuminate\Support\Facades\Response;
15	use Illuminate\Support\Str;
16	use OpenSpout\Common\Entity\Row;
17	use OpenSpout\Writer\XLSX\Writer;
18	use Symfony\Component\HttpFoundation\StreamedResponse;
19	
20	/**
21	 * Esporta l'anagrafica prodotti (filtrata per Category1) in XLSX, per far
22	 * rivedere al cliente il risultato del merge v1/v2 (vedi
23	 * .docs/import-prodotti-indoor.md).
24	 *
25	 * Colonne fisse (collezione, categoria, nome, materiali, tessuti) + colonne
26	 * dinamiche, una per ogni attributo tecnico PIM effettivamente valorizzato
27	 * nello scope esportato — lo schema attributi varia per ProductType, quindi
28	 * l'insieme delle colonne non è noto a priori (prima passata sui prodotti per
29	 * raccoglierle, coerente con `ProductResource::resolveAttributes()` lato API).
30	 */
31	class ExportProductsAction
32	{
33	    public static function make(string $name = 'export'): Action
34	    {
35	        return Action::make($name)
36	            ->label(__('product.export.label'))
37	            ->icon(Heroicon::OutlinedArrowDownTray)
38	            ->modalHeading(__('product.export.modal_heading'))
39	            ->schema([
40	                Select::make('category_1_id')
41	                    ->label(__('product.export.scope'))
42	                    ->placeholder(__('product.export.scope_placeholder'))
43	                    ->options(fn () => Category1::orderBy('name->it')->pluck('name', 'id')),
44	            ])
45	            ->action(function (array $data): StreamedResponse {
46	                $raw = $data['category_1_id'] ?? null;
47	
48	                return self::export(is_numeric($raw) ? (int) $raw : null);
49	            });
50	    }
51	
52	    private static function export(?int $categoryOneId): StreamedResponse
53	    {
54	        $products = Product::query()
55	            ->with(['category2.category1', 'productType', 'parent.category2', 'materials', 'fabrics'])
56	            ->when(
57	                $categoryOneId !== null,
58	                fn ($query) => $query->whereHas('category2', fn ($q) => $q->where('category_1_id', $categoryOneId)),
59	            )
60	            ->orderBy('category_2_id')
61	            ->get();
62	
63	        $attributeColumns = self::collectAttributeColumns($products);
64	
65	        $tmpPath = tempnam(sys_get_temp_dir(), 'export-prodotti-');
66	        if ($tmpPath === false) {
67	            throw new \RuntimeException('Impossibile creare il file temporaneo per l\'export.');
68	        }
69	
70	        $writer = new Writer();
71	        $writer->openToFile($tmpPath);
72	        $writer->addRow(Row::fromValues(self::header($attributeColumns)));
73	
74	        foreach ($products as $product) {
75	            $writer->addRow(Row::fromValues(self::row($product, $attributeColumns)));
76	        }
77	
78	        $writer->close();
79	
80	        $category1 = $categoryOneId !== null ? Category1::find($categoryOneId) : null;
81	        $scopeSlug = $category1 !== null ? Str::slug(self::displayString($category1->name)) : 'tutti';
82	        $filename = "prodotti-{$scopeSlug}-" . now()->format('Y-m-d') . '.xlsx';
83	
84	        return Response::streamDownload(function () use ($tmpPath): void {
85	            readfile($tmpPath);
86	            unlink($tmpPath);
87	        }, $filename, [
88	            'Content-Type' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
89	        ]);
90	    }
91	
92	    /**
93	     * Prima passata: chiave attributo → label leggibile, per ogni attributo
94	     * effettivamente valorizzato in almeno un prodotto dello scope esportato.
95	     *
96	     * @param Collection<int, Product> $products
97	     * @return array<string, string>
98	     */
99	    private static function collectAttributeColumns(Collection $products): array
100	    {
101	        $columns = [];
102	
103	        foreach ($products as $product) {
104	            $schema = $product->attributeSchema();
105	            if ($schema === null) {
106	                continue;
107	            }
108	
109	            foreach (array_keys($schema->attributes()) as $key) {
110	                if (isset($columns[$key])) {
111	                    continue;
112	                }
113	
114	                $value = $product->attr($key, 'it');
115	                if ($value === null || $value === '') {
116	                    continue;
117	                }
118	
119	                $columns[$key] = $product->attrLabel($key, 'it');
120	            }
121	        }
122	
123	        asort($columns);
124	
125	        return $columns;
126	    }
127	
128	    /**
129	     * @param array<string, string> $attributeColumns
130	     * @return list<string>
131	     */
132	    private static function header(array $attributeColumns): array
133	    {
134	        return [
135	            __('product.export.columns.category_1'),
136	            __('product.export.columns.category_2'),
137	            __('product.export.columns.product_type'),
138	            __('product.export.columns.name'),
139	            __('product.export.columns.slug'),
140	            __('product.export.columns.parent'),
141	            __('product.export.columns.materials'),
142	            __('product.export.columns.fabrics'),
143	            ...array_values($attributeColumns),
144	        ];
145	    }
146	
147	    /**
148	     * @param array<string, string> $attributeColumns
149	     * @return list<string>
150	     */
151	    private static function row(Product $product, array $attributeColumns): array
152	    {
153	        $cells = [
154	            self::displayString($product->category2?->category1?->getTranslation('name', 'it')),
155	            self::displayString($product->category2?->getTranslation('name', 'it')),
156	            self::displayString($product->productType?->name),
157	            self::displayString($product->getTranslation('name', 'it')),
158	            self::displayString($product->slug),
159	            $product->parent !== null ? self::displayString($product->parent->catalogName('it')) : '',
160	            $product->materials->map(fn ($m) => self::displayString($m->getTranslation('name', 'it')))->implode(', '),
161	            $product->fabrics->map(fn ($f) => self::displayString($f->getTranslation('name', 'it')))->implode(', '),
162	        ];
163	
164	        foreach (array_keys($attributeColumns) as $key) {
165	            $cells[] = self::formatAttribute($product, $key);
166	        }
167	
168	        return $cells;
169	    }
170	
171	    private static function formatAttribute(Product $product, string $key): string
172	    {
173	        $type = $product->attributeSchema()?->getType($key);
174	        $value = $product->attr($key, 'it');
175	
176	        if ($value === null || $value === '') {
177	            return '';
178	        }
179	
180	        if ($type?->kind() === Type::Bool) {
181	            return $value ? __('product.export.bool_yes') : __('product.export.bool_no');
182	        }
183	
184	        if ($type?->kind() === Type::Enum && is_string($value)) {
185	            $value = $product->attrOption($key, $value, 'it');
186	        }
187	
188	        $unit = $type?->getUnit();
189	        $display = self::displayString($value);
190	
191	        return $unit !== null && $unit !== '' ? "{$display} {$unit}" : $display;
192	    }
193	
194	    /**
195	     * Stringifica un valore mixed (proveniente da colonne JSON/translatable)
196	     * in modo tipabile per PHPStan: solo gli scalari sono castati, il resto
197	     * (array residuo da un fallback di traduzione mancante, ad es.) diventa
198	     * stringa vuota.
199	     */
200	    private static function displayString(mixed $value): string
201	    {
202	        if (is_string($value)) {
203	            return $value;
204	        }
205	
206	        return is_scalar($value) ? (string) $value : '';
207	    }
208	}
209

