    // solo nel nome/specifica: cerco il marker testuale sia sul prodotto
    // sia sulla collezione v1 grezza (es. "Adone Wall").
    $productText = mb_strtolower((string) $product->specifica . ' ' . (string) $product->getTranslation('name', 'it'));
    $wantsWall = str_contains($productText, 'parete') || str_contains($productText, 'wall');
    $wallCandidates = array_values(array_filter($candidates, fn ($c) => str_contains(mb_strtolower($c['collezione_raw']), 'wall')));
    if ($wallCandidates !== [] && count($wallCandidates) < count($candidates)) {
        $nonWallCandidates = array_values(array_filter($candidates, fn ($c) => ! str_contains(mb_strtolower($c['collezione_raw']), 'wall')));
        if ($wantsWall && $wallCandidates !== []) {
            return $wallCandidates[0];
        }
        if (! $wantsWall && $nonWallCandidates !== []) {
            return $nonWallCandidates[0];
        }
    }

    // Suffisso lettera singola (es. "Diesis .A/.B/.C" ↔ specifica "A"/"B"/"C"),
    // strippato dalla collezione per la chiave di raggruppamento.
    $specifica = (string) $product->specifica;
    if (preg_match('/^[a-z]$/i', $specifica) === 1) {
        foreach ($candidates as $c) {
            if (preg_match('/\.' . preg_quote($specifica, '/') . '$/i', $c['collezione_raw']) === 1) {
                return $c;
            }
        }
    }

    // Codice numerico nella specifica (es. "228", "D60") == larghezza v1
    // (Karin: "Credenza 228/278" ↔ 228x54x88/278x54x88; Toulouse D60/D90).
    if (preg_match('/(\d+)/', $specifica, $m) === 1) {
        $wantedWidth = (float) $m[1];
        foreach ($candidates as $c) {
            if ($c['width'] !== null && abs($c['width'] - $wantedWidth) < 0.5) {
                return $c;
            }
        }
    }

    // Euristica taglia: S/M/L/XL/Plus L/Plus XL → ordine dimensionale
    // crescente (decisione esplicita, v. doc classe).
    $taglia = $product->attr('taglia');
    if (is_string($taglia) && isset(self::TAGLIA_ORDER[$taglia])) {
        $resolved = $this->resolveByTagliaOrder($product, $candidates, $taglia);
        if ($resolved !== null) {
            return $resolved;
        }
    }

    // Euristica forma Q/R (quadrato/rettangolare) senza label v1: dedotta
    // dai numeri (decisione esplicita, v. doc classe). Per gli specchi il
    // piano significativo è width×height (depth = spessore, ~5cm); per i
    // tavoli è width×depth (height = altezza gambe, irrilevante per la forma).
    if ($forma === 'Q' || $forma === 'R') {
        $isMirror = $product->productType?->slug === 'specchi';
        foreach ($candidates as $c) {
            $other = $isMirror ? $c['height'] : $c['depth'];
            if ($c['width'] === null || $other === null) {
                continue;
            }
            $isSquare = abs($c['width'] - $other) < 5.0;
            if (($forma === 'Q') === $isSquare) {
                return $c;
            }
        }
    }

    return null;
}

