1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Filament\Resources\Products\Actions;
6	
7	use App\Models\Category1;
8	use App\Models\Product;
9	use AtrioTeam\DigitalHub\Pim\Enum\Type;
10	use Filament\Actions\Action;
11	use Filament\Forms\Components\Select;
12	use Filament\Support\Icons\Heroicon;
13	use Illuminate\Database\Eloquent\Collection;
14	use Illuminate\Support\Facades\Response;
15	use Illuminate\Support\Str;
16	use OpenSpout\Common\Entity\Row;
17	use OpenSpout\Writer\XLSX\Writer;
18	use Symfony\Component\HttpFoundation\StreamedResponse;
19	
20	/**
21	 * Esporta l'anagrafica prodotti (filtrata per Category1) in XLSX, per far
22	 * rivedere al cliente il risultato del merge v1/v2 (vedi
23	 * .docs/import-prodotti-indoor.md).
24	 *
25	 * Colonne fisse (collezione, categoria, nome) + colonne dinamiche, una per
26	 * ogni attributo tecnico PIM effettivamente valorizzato nello scope
27	 * esportato — lo schema attributi varia per ProductType, quindi l'insieme
28	 * delle colonne non è noto a priori (prima passata sui prodotti per
29	 * raccoglierle, coerente con `ProductResource::resolveAttributes()` lato API).
30	 *
31	 * Materiali/tessuti volutamente esclusi per ora (in revisione, vedi §9.1
32	 * import-prodotti-indoor.md sulla granularità "grezzo per tipologia").
33	 */
34	class ExportProductsAction
35	{
36	    public static function make(string $name = 'export'): Action
37	    {
38	        return Action::make($name)
39	            ->label(__('product.export.label'))
40	            ->icon(Heroicon::OutlinedArrowDownTray)
41	            ->modalHeading(__('product.export.modal_heading'))
42	            ->schema([
43	                Select::make('category_1_id')
44	                    ->label(__('product.export.scope'))
45	                    ->placeholder(__('product.export.scope_placeholder'))
46	                    ->options(fn () => Category1::orderBy('name->it')->pluck('name', 'id')),
47	            ])
48	            ->action(function (array $data): StreamedResponse {
49	                $raw = $data['category_1_id'] ?? null;
50	
51	                return self::export(is_numeric($raw) ? (int) $raw : null);
52	            });
53	    }
54	
55	    private static function export(?int $categoryOneId): StreamedResponse
56	    {
57	        $products = Product::query()
58	            ->with(['category2.category1', 'productType', 'parent.category2'])
59	            ->when(
60	                $categoryOneId !== null,
61	                fn ($query) => $query->whereHas('category2', fn ($q) => $q->where('category_1_id', $categoryOneId)),
62	            )
63	            ->orderBy('category_2_id')
64	            ->get();
65	
66	        $attributeColumns = self::collectAttributeColumns($products);
67	
68	        $tmpPath = tempnam(sys_get_temp_dir(), 'export-prodotti-');
69	        if ($tmpPath === false) {
70	            throw new \RuntimeException('Impossibile creare il file temporaneo per l\'export.');
71	        }
72	
73	        $writer = new Writer();
74	        $writer->openToFile($tmpPath);
75	        $writer->addRow(Row::fromValues(self::header($attributeColumns)));
76	
77	        foreach ($products as $product) {
78	            $writer->addRow(Row::fromValues(self::row($product, $attributeColumns)));
79	        }
80	
81	        $writer->close();
82	
83	        $category1 = $categoryOneId !== null ? Category1::find($categoryOneId) : null;
84	        $scopeSlug = $category1 !== null ? Str::slug(self::displayString($category1->name)) : 'tutti';
85	        $filename = "prodotti-{$scopeSlug}-" . now()->format('Y-m-d') . '.xlsx';
86	
87	        return Response::streamDownload(function () use ($tmpPath): void {
88	            readfile($tmpPath);
89	            unlink($tmpPath);
90	        }, $filename, [
91	            'Content-Type' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
92	        ]);
93	    }
94	
95	    /**
96	     * Prima passata: chiave attributo → label leggibile, per ogni attributo
97	     * effettivamente valorizzato in almeno un prodotto dello scope esportato.
98	     *
99	     * @param Collection<int, Product> $products
100	     * @return array<string, string>
101	     */
102	    private static function collectAttributeColumns(Collection $products): array
103	    {
104	        $columns = [];
105	
106	        foreach ($products as $product) {
107	            $schema = $product->attributeSchema();
108	            if ($schema === null) {
109	                continue;
110	            }
111	
112	            foreach (array_keys($schema->attributes()) as $key) {
113	                if (isset($columns[$key])) {
114	                    continue;
115	                }
116	
117	                $value = $product->attr($key, 'it');
118	                if ($value === null || $value === '') {
119	                    continue;
120	                }
121	
122	                $columns[$key] = $product->attrLabel($key, 'it');
123	            }
124	        }
125	
126	        asort($columns);
127	
128	        return $columns;
129	    }
130	
131	    /**
132	     * @param array<string, string> $attributeColumns
133	     * @return list<string>
134	     */
135	    private static function header(array $attributeColumns): array
136	    {
137	        return [
138	            __('product.export.columns.category_1'),
139	            __('product.export.columns.category_2'),
140	            __('product.export.columns.product_type'),
141	            __('product.export.columns.name'),
142	            __('product.export.columns.slug'),
143	            __('product.export.columns.parent'),
144	            ...array_values($attributeColumns),
145	        ];
146	    }
147	
148	    /**
149	     * @param array<string, string> $attributeColumns
150	     * @return list<string>
151	     */
152	    private static function row(Product $product, array $attributeColumns): array
153	    {
154	        $cells = [
155	            self::displayString($product->category2?->category1?->getTranslation('name', 'it')),
156	            self::displayString($product->category2?->getTranslation('name', 'it')),
157	            self::displayString($product->productType?->name),
158	            self::displayString($product->getTranslation('name', 'it')),
159	            self::displayString($product->slug),
160	            $product->parent !== null ? self::displayString($product->parent->catalogName('it')) : '',
161	        ];
162	
163	        foreach (array_keys($attributeColumns) as $key) {
164	            $cells[] = self::formatAttribute($product, $key);
165	        }
166	
167	        return $cells;
168	    }
169	
170	    private static function formatAttribute(Product $product, string $key): string
171	    {
172	        $type = $product->attributeSchema()?->getType($key);
173	        $value = $product->attr($key, 'it');
174	
175	        if ($value === null || $value === '') {
176	            return '';
177	        }
178	
179	        if ($type?->kind() === Type::Bool) {
180	            return $value ? __('product.export.bool_yes') : __('product.export.bool_no');
181	        }
182	
183	        if ($type?->kind() === Type::Enum && is_string($value)) {
184	            $value = $product->attrOption($key, $value, 'it');
185	        }
186	
187	        $unit = $type?->getUnit();
188	        $display = self::displayString($value);
189	
190	        return $unit !== null && $unit !== '' ? "{$display} {$unit}" : $display;
191	    }
192	
193	    /**
194	     * Stringifica un valore mixed (proveniente da colonne JSON/translatable)
195	     * in modo tipabile per PHPStan: solo gli scalari sono castati, il resto
196	     * (array residuo da un fallback di traduzione mancante, ad es.) diventa
197	     * stringa vuota.
198	     */
199	    private static function displayString(mixed $value): string
200	    {
201	        if (is_string($value)) {
202	            return $value;
203	        }
204	
205	        return is_scalar($value) ? (string) $value : '';
206	    }
207	}
