1	<?php
2	
3	declare(strict_types=1);
4	
5	namespace App\Console\Commands;
6	
7	use App\Models\Category1;
8	use App\Models\Material;
9	use AtrioTeam\DigitalHub\Tags\Enum\TagTarget;
10	use AtrioTeam\DigitalHub\Tags\Models\Tag;
11	use AtrioTeam\DigitalHub\Tags\Models\TagCategory;
12	use AtrioTeam\DigitalHub\Tags\Models\TagGroup;
13	use Illuminate\Console\Command;
14	use Illuminate\Support\Collection;
15	use Illuminate\Support\Facades\DB;
16	use Illuminate\Support\Str;
17	use OpenSpout\Reader\XLSX\Reader;
18	
19	/**
20	 * Import dei tag anagrafica dei materiali dal foglio "Materiali" del file
21	 * filtri INTERIOR. Speculare a {@see ImportFiltriTessuti}.
22	 *
23	 * ⚠️ **Punta ancora al file vecchio** (`indoor/materiali-tessuti/INTERIOR -
24	 * materiali e tessuti filtri.xlsx`): la consegna del 21 luglio ha separato i
25	 * filtri tessuti in un file proprio, e il corrispettivo per i materiali non è
26	 * ancora arrivato. Quando arriverà basta ripuntare `--file` (il foglio
27	 * "Materiali" della mappatura 21/07 aveva già una tipologia in più, Ceramica).
28	 *
29	 * Il foglio è a colonna singola: righe intestazione di blocco (Tipologia,
30	 * Finitura, Colore) seguite dai valori; separatori (`____`) e righe vuote
31	 * ignorati. Ogni blocco diventa una TagCategory dentro il gruppo "Filtri
32	 * Materiali Interior" (entity_type=material, target=entity, Category1 Indoor).
33	 *
34	 * A differenza dei tessuti, qui **il file non fa fede sui nomi**: i tag già
35	 * presenti non vengono rinominati né rimossi, e il match è tollerante ai
36	 * suffissi tra parentesi ("Lucido (Glossy)" ≡ "Lucido"). Su questi tag le
37	 * traduzioni si curano in admin e devono sopravvivere ai rilanci.
38	 *
39	 * I tag Finitura vengono agganciati ai `Material` la cui finitura è desumibile
40	 * dallo slug — l'unica associazione tag↔entità che i materiali hanno oggi.
41	 */
42	class ImportFiltriMateriali extends Command
43	{
44	    protected $signature = 'app:import-filtri-materiali '
45	        . '{--file=storage/app/private/import/indoor/materiali-tessuti/INTERIOR - materiali e tessuti filtri.xlsx} '
46	        . '{--fresh : Svuota i tag delle categorie interessate prima di reimportare}';
47	
48	    protected $description = 'Import dei tag anagrafica materiali dal file filtri INTERIOR (foglio "Materiali")';
49	
50	    private const SHEET = 'Materiali';
51	
52	    /**
53	     * Intestazioni di blocco (chiave normalizzata) → nome visualizzato della
54	     * TagCategory. Nel foglio compaiono con casing misto (es. "FINITURA").
55	     *
56	     * @var array<string, string>
57	     */
58	    private const BLOCKS = [
59	        'tipologia' => 'Tipologia',
60	        'finitura' => 'Finitura',
61	        'colore' => 'Colore',
62	    ];
63	
64	    public function handle(): int
65	    {
66	        $file = (string) $this->option('file');
67	        if (! is_file($file)) {
68	            $this->error("File non trovato: {$file}");
69	
70	            return self::FAILURE;
71	        }
72	
73	        $blocks = $this->parseSheet($file);
74	        if ($blocks === null) {
75	            $this->error('Foglio "' . self::SHEET . '" non trovato nel file.');
76	
77	            return self::FAILURE;
78	        }
79	
80	        // la destinazione è un presupposto della tassonomia, non un dato da
81	        // importare: se manca la si crea, così il comando non dipende da un
82	        // seeder lanciato prima
83	        $indoor = Category1::query()->firstOrCreate(
84	            ['slug' => 'indoor'],
85	            ['name' => ['it' => 'Interior', 'en' => 'Interior']],
86	        );
87	
88	        $stats = ['categories' => 0, 'tags' => 0, 'materials tagged' => 0];
89	
90	        DB::transaction(function () use ($indoor, $blocks, &$stats): void {
91	            $group = $this->resolveGroup($indoor);
92	
93	            $categorySort = 0;
94	            foreach ($blocks as $blockName => $values) {
95	                $category = TagCategory::query()->updateOrCreate(
96	                    ['tag_group_id' => $group->id, 'slug' => Str::slug($blockName)],
97	                    ['name' => ['it' => $blockName, 'en' => $blockName], 'sort' => $categorySort++],
98	                );
99	                $stats['categories']++;
100	
101	                if ($this->option('fresh')) {
102	                    Tag::query()->where('tag_category_id', $category->id)->delete();
103	                }
104	
105	                // tag esistenti indicizzati per nome normalizzato: i già
106	                // presenti restano intatti (nome compreso), i nuovi si creano
107	                $existing = Tag::query()
108	                    ->where('tag_category_id', $category->id)
109	                    ->get()
110	                    ->keyBy(function (Tag $tag): string {
111	                        $name = $tag->getTranslation('name', 'it');
112	
113	                        return $this->normalizeTagName(is_string($name) ? $name : '');
114	                    });
115	
116	                foreach ($values as $value) {
117	                    $key = $this->normalizeTagName($value);
118	                    $stats['tags']++;
119	
120	                    if ($existing->has($key)) {
121	                        continue;
122	                    }
123	
124	                    $tag = new Tag();
125	                    $tag->tag_category_id = $category->id;
126	                    $tag->setTranslations('name', ['it' => $value, 'en' => $value]);
127	                    $tag->save();
128	                    $existing->put($key, $tag);
129	                }
130	
131	                if ($blockName === self::BLOCKS['finitura']) {
132	                    $stats['materials tagged'] = $this->attachFinishTags($existing);
133	                }
134	            }
135	        });
136	
137	        $this->info('Import tag materiali completato.');
138	        $this->table(
139	            ['Metrica', 'Valore'],
140	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
141	        );
142	
143	        return self::SUCCESS;
144	    }
145	
146	    /**
147	     * Associa i tag Lucido/Opaco ai Material la cui finitura è desumibile dallo
148	     * slug: suffisso `-glossy`/`-matt` per Essenze/Laccati (varianti generate
149	     * da `app:import-materials`), prefisso `polished-`/`matt-` per i Metalli
150	     * (finitura già nel nome catalogo). I Marmi non hanno finitura.
151	     *
152	     * @param Collection<string, Tag> $tags tag della categoria "Finitura", chiave = nome normalizzato
153	     */
154	    private function attachFinishTags(Collection $tags): int
155	    {
156	        $lucido = $tags->get('lucido');
157	        $opaco = $tags->get('opaco');
158	        if ($lucido === null || $opaco === null) {
159	            return 0;
160	        }
161	
162	        $matches = [
163	            [$lucido, ['%-glossy', 'polished-%']],
164	            [$opaco, ['%-matt', 'matt-%']],
165	        ];
166	
167	        $tagged = 0;
168	        foreach ($matches as [$tag, $patterns]) {
169	            $materials = Material::query()
170	                ->where(function ($query) use ($patterns): void {
171	                    foreach ($patterns as $pattern) {
172	                        $query->orWhere('slug', 'like', $pattern);
173	                    }
174	                })
175	                ->get();
176	
177	            foreach ($materials as $material) {
178	                $material->tags()->syncWithoutDetaching([$tag->id]);
179	                $tagged++;
180	            }
181	        }
182	
183	        return $tagged;
184	    }
185	
186	    /**
187	     * Legge il foglio Materiali e raggruppa i valori per blocco.
188	     * Ritorna null se il foglio non esiste.
189	     *
190	     * @return array<string, list<string>>|null
191	     */
192	    private function parseSheet(string $file): ?array
193	    {
194	        $blocks = null;
195	        $current = null;
196	
197	        $reader = new Reader();
198	        $reader->open($file);
199	        foreach ($reader->getSheetIterator() as $sheet) {
200	            if ($sheet->getName() !== self::SHEET) {
201	                continue;
202	            }
203	            $blocks = [];
204	
205	            foreach ($sheet->getRowIterator() as $row) {
206	                $raw = ($row->getCells()[0] ?? null)?->getValue();
207	                $value = is_scalar($raw) ? trim((string) $raw) : '';
208	                if ($value === '' || preg_match('/^_+$/', $value) === 1) {
209	                    continue;
210	                }
211	
212	                $blockName = self::BLOCKS[$this->normalize($value)] ?? null;
213	                if ($blockName !== null) {
214	                    $current = $blockName;
215	                    $blocks[$current] ??= [];
216	
217	                    continue;
218	                }
219	
220	                if ($current === null) {
221	                    $this->warn("Valore fuori da ogni blocco, ignorato: {$value}");
222	
223	                    continue;
224	                }
225	
226	                $blocks[$current][] = $value;
227	            }
228	
229	            break;
230	        }
231	        $reader->close();
232	
233	        return $blocks;
234	    }
235	
236	    /** Gruppo tag anagrafica dei materiali Interior (creato se assente). */
237	    private function resolveGroup(Category1 $indoor): TagGroup
238	    {
239	        return TagGroup::query()
240	            ->where('entity_type', 'material')
241	            ->where('target', TagTarget::Entity)
242	            ->where('category_1_id', $indoor->id)
243	            ->first()
244	            ?? TagGroup::query()->create([
245	                'entity_type' => 'material',
246	                'target' => TagTarget::Entity,
247	                'category_1_id' => $indoor->id,
248	                'name' => ['it' => 'Filtri Materiali Interior', 'en' => 'Interior material filters'],
249	            ]);
250	    }
251	
252	    private function normalize(string $value): string
253	    {
254	        return trim((string) preg_replace('/\s+/', ' ', mb_strtolower($value)));
255	    }
256	
257	    /**
258	     * Forma canonica per il matching: oltre alla normalize, ignora i suffissi
259	     * tra parentesi ("Lucido (Glossy)" ≡ "Lucido").
260	     */
261	    private function normalizeTagName(string $value): string
262	    {
263	        return $this->normalize((string) preg_replace('/\s*\([^)]*\)/', ' ', $value));
264	    }
265	}
