3	declare(strict_types=1);
4	
5	namespace App\Console\Commands;
6	
7	use App\Models\Fabric;
8	use App\Models\FabricCategory;
9	use App\Models\Product;
10	use Illuminate\Console\Command;
11	use Illuminate\Support\Str;
12	use OpenSpout\Reader\XLSX\Reader;
13	
14	/**
15	 * Import della relazione prodotto ↔ tessuto (`fabric_product`) dalla matrice
16	 * finiture. Prima viveva dentro `app:import-indoor --fabrics-only`, che per
17	 * risincronizzare il pivot doveva rileggere l'intero file prodotti: qui è un
18	 * comando a sé, che non tocca né prodotti né collezioni.
19	 *
20	 * **La matrice non arriva al singolo colore**: dice quali *tipologie* di
21	 * tessuto sono disponibili per un prodotto (una colonna per tipologia, valore
22	 * booleano). L'associazione viene quindi popolata con tutti i `Fabric` della
23	 * tipologia risolta — è il massimo dettaglio che la sorgente consente, vedi
24	 * roadmap #30.
25	 *
26	 * Le colonne della matrice sono individuate **per nome di intestazione**, non
27	 * per posizione: la stessa matrice compare in più file con le colonne tessuto
28	 * in posizioni diverse.
29	 *
30	 * Il prodotto si ritrova per slug, ricalcolato dalle colonne normalizzate
31	 * "import collezione" + "import nome prodotto" allo stesso modo di
32	 * `app:import-indoor` (deterministico a parità di file e ordine righe).
33	 * **Un file senza quelle colonne non è utilizzabile** e il comando si ferma
34	 * dicendolo, invece di associare a caso: è il caso di `Finiture e materiali
35	 * Capital.xlsx`, che ha la matrice ma solo le colonne grezze
36	 * COLLEZIONE/SPECIFICA PRODOTTO — quelle non identificano il prodotto a
37	 * catalogo, e nemmeno le sue righe corrispondono a quelle del file di lavoro
38	 * (278 contro 277, con 175 triplette diverse).
39	 *
40	 * Prerequisiti: i prodotti a catalogo (`app:import-indoor`) e i tessuti
41	 * (`app:import-fabrics`). Idempotente: `sync()` per prodotto.
42	 */
43	class ImportFabricsRelProduct extends Command
44	{
45	    protected $signature = 'app:import-fabrics-rel-product '
46	        . '{--file=storage/app/private/import/indoor/prodotti_v2_import.xlsx}';
47	
48	    protected $description = 'Import della relazione prodotto ↔ tessuto dalla matrice finiture';
49	
50	    /**
51	     * Intestazioni delle colonne che identificano il prodotto. Sono quelle
52	     * normalizzate a mano nel file di lavoro: le grezze non bastano.
53	     */
54	    private const COL_COLLECTION = 'import collezione';
55	
56	    private const COL_NAME = 'import nome prodotto';
57	
58	    /** Intestazione della categoria prodotto (serve per escludere i wrapper). */
59	    private const COL_CATEGORY = 'categoria';
60	
61	    /**
62	     * Colonne tessuto della matrice (intestazione lowercase) → tipologie
63	     * `FabricCategory` per slug. La col "pelli nabuk, soft grain, vintage"
64	     * mappa 3 pelli distinte del catalogo e "tessuti luxury and exclusive" le
65	     * due tipologie che il file tessuti tiene separate. La col "nabuk treccia"
66	     * non ha più una tipologia corrispondente e viene ignorata.
67	     *
68	     * @var array<string, list<string>>
69	     */
70	    private const FABRIC_MAP = [
71	        'chenille' => ['lord-fabric'],
72	        'boucle' => ['boucle-fabric'],
73	        'york' => ['york-fabric'],
74	        'velluto' => ['velvet'],
75	        'pelli nabuk, soft grain, vintage' => ['nabuk-leather', 'soft-grain-leather', 'vintage-leather'],
76	        'pelle sintetica' => ['synthetic-leather'],
77	        'tessuti luxury and exclusive' => ['luxury-fabrics', 'exclusive-fabrics'],
78	    ];
79	
80	    /** Il wrapper "divano modulare" è un'entità logica: non ha tessuti. */
81	    private const WRAPPER_CATEGORY = 'divani modulari';
82	
83	    /** @var array<string, list<int>> slug tipologia → id dei suoi colori */
84	    private array $fabricsByCategory = [];
85	
86	    /** @var array<string, true> slug già assegnati in questo run */
87	    private array $usedSlugs = [];
88	
89	    public function handle(): int
90	    {
91	        $file = (string) $this->option('file');
92	        if (! is_file($file)) {
93	            $this->error("File non trovato: {$file}");
94	
95	            return self::FAILURE;
96	        }
97	
98	        $this->fabricsByCategory = [];
99	        $this->usedSlugs = [];
100	
101	        $stats = ['rows' => 0, 'products' => 0, 'attached' => 0, 'not found' => 0];
102	        $notFound = [];
103	
104	        $reader = new Reader();
105	        $reader->open($file);
106	
107	        $header = null;
108	        foreach ($reader->getSheetIterator() as $sheet) {
109	            foreach ($sheet->getRowIterator() as $row) {
110	                $cells = array_values(array_map(fn ($c): mixed => $c->getValue(), $row->getCells()));
111	
112	                if ($header === null) {
113	                    $header = array_map(fn ($v): string => $this->normalize($this->s($v)), $cells);
114	
115	                    $missing = array_diff([self::COL_COLLECTION, self::COL_NAME], $header);
116	                    if ($missing !== []) {
117	                        $reader->close();
118	                        $this->error(
119	                            'Il file non ha le colonne che identificano il prodotto ('
120	                            . implode(', ', $missing) . '): impossibile ritrovare i prodotti a catalogo. '
121	                            . 'Serve la matrice con le colonne normalizzate, es. '
122	                            . 'storage/app/private/import/indoor/prodotti_v2_import.xlsx',
123	                        );
124	
125	                        return self::FAILURE;
126	                    }
127	
128	                    continue;
129	                }
130	
131	                $collection = $this->s($cells[$this->column($header, self::COL_COLLECTION) ?? -1] ?? '');
132	                $name = $this->s($cells[$this->column($header, self::COL_NAME) ?? -1] ?? '');
133	                if ($collection === '' || $name === '') {
134	                    continue; // riga non-prodotto / vuota
135	                }
136	                $stats['rows']++;
137	
138	                $categoryColumn = $this->column($header, self::COL_CATEGORY);
139	                $category = $categoryColumn === null ? '' : $this->normalize($this->s($cells[$categoryColumn] ?? ''));
140	
141	                // Riclassificazione Clori: la riga "Comodino" con Essenze
142	                // attivo è in realtà un Comò. Va applicata anche qui, perché
143	                // entra nello slug con cui `app:import-indoor` ha creato il
144	                // prodotto. Vedi .docs/import-prodotti-indoor.md §9.
145	                if ($this->normalize($collection) === 'clori'
146	                    && $category === 'comodino'
147	                    && $this->isTrue($cells[$this->column($header, 'essenze') ?? -1] ?? null)) {
148	                    $category = 'comò';
149	                    $name = 'Comò';
150	                }
151	
152	                // lo slug è deterministico a parità di file e ordine righe:
153	                // lo ricalcoliamo per ritrovare il prodotto già a catalogo
154	                $slug = $this->uniqueSlug($collection . ' ' . $name);
155	
156	                if ($category === self::WRAPPER_CATEGORY) {
157	                    continue;
158	                }
159	
160	                $product = Product::query()->where('slug', $slug)->first();
161	                if (! $product instanceof Product) {
162	                    $stats['not found']++;
163	                    $notFound[$slug] = true;
164	
165	                    continue;
166	                }
167	
168	                $stats['products']++;
169	                $stats['attached'] += $this->attach($product, $cells, $header);
170	            }
171	
172	            break;
173	        }
174	        $reader->close();
175	
176	        if ($notFound !== []) {
177	            $this->warn('Prodotti non trovati a catalogo (' . count($notFound) . '): '
178	                . implode(', ', array_slice(array_keys($notFound), 0, 10))
179	                . (count($notFound) > 10 ? ', …' : ''));
180	        }
181	
182	        $this->info('Import relazione prodotto ↔ tessuto completato.');
183	        $this->table(
184	            ['Metrica', 'Valore'],
185	            collect($stats)->map(fn ($v, $k): array => [$k, $v])->values()->all(),
186	        );
187	
188	        return self::SUCCESS;
189	    }
190	
191	    /**
192	     * Allinea i tessuti del prodotto alle tipologie flaggate sulla sua riga.
193	     *
194	     * @param list<mixed> $cells
195	     * @param list<string> $header
196	     */
197	    private function attach(Product $product, array $cells, array $header): int
198	    {
199	        $fabricIds = [];
200	
201	        foreach ($header as $i => $name) {
202	            if (! isset(self::FABRIC_MAP[$name]) || ! $this->isTrue($cells[$i] ?? null)) {
203	                continue;
204	            }
205	
206	            foreach (self::FABRIC_MAP[$name] as $categorySlug) {
207	                foreach ($this->fabricsOf($categorySlug) as $id) {
208	                    $fabricIds[] = $id;
209	                }
210	            }
211	        }
212	
213	        $fabricIds = array_values(array_unique($fabricIds));
214	        $product->fabrics()->sync($fabricIds);
215	
216	        return count($fabricIds);
217	    }
218	
219	    /**
220	     * Id dei colori di una tipologia, risolti una volta sola per run.
221	     *
222	     * @return list<int>
223	     */
224	    private function fabricsOf(string $categorySlug): array
225	    {
226	        return $this->fabricsByCategory[$categorySlug] ??= (function () use ($categorySlug): array {
227	            $category = FabricCategory::query()->where('slug', $categorySlug)->first();
228	            if (! $category instanceof FabricCategory) {
229	                $this->warn("Tipologia tessuto non trovata, ignorata: {$categorySlug}");
230	
231	                return [];
232	            }
233	
234	            /** @var list<int> $ids */
235	            $ids = Fabric::query()->where('fabric_category_id', $category->id)->pluck('id')->all();
236	
237	            return $ids;
238	        })();
239	    }
240	
241	    /**
242	     * Indice della colonna con quell'intestazione, null se assente.
243	     *
244	     * @param list<string> $header
245	     */
246	    private function column(array $header, string $name): ?int
247	    {
248	        $index = array_search($name, $header, true);
249	
250	        return $index === false ? null : $index;
251	    }
252	
253	    /** Stesso slug di `app:import-indoor`: dipende dall'ordine delle righe. */
254	    private function uniqueSlug(string $base): string
255	    {
256	        $slug = Str::slug($base);
257	        $candidate = $slug;
258	        $i = 2;
259	        while (isset($this->usedSlugs[$candidate])) {
260	            $candidate = "{$slug}-{$i}";
261	            $i++;
262	        }
263	        $this->usedSlugs[$candidate] = true;
264	
265	        return $candidate;
266	    }
267	
268	    private function isTrue(mixed $value): bool
269	    {
270	        $v = mb_strtoupper($this->s($value));
271	
272	        return $v === '=TRUE()' || $v === 'TRUE' || $v === '1';
273	    }
274	
275	    private function normalize(string $value): string
276	    {
277	        return trim((string) preg_replace('/\s+/u', ' ', mb_strtolower($value)));
278	    }
279	
280	    private function s(mixed $value): string
281	    {
282	        return is_scalar($value) ? trim((string) $value) : '';
283	    }
284	}
