    // query (scope di default) ma continuano a occupare lo slug univoco,
    // facendo fallire il firstOrCreate della prossima collezione/prodotto.
    $collectionIds = Category2::withTrashed()
        ->where('category_1_id', $indoor->id)
        ->pluck('id');

    // forceDelete, non soft delete: questo è un rebuild ("nessun ID da
    // preservare", v. doc), non una cancellazione da admin — lasciare
    // scarti soft-deleted rompe qualunque rebuild successivo sullo stesso
    // slug (unique constraint non è scoped su deleted_at). Elimina prima i
    // figli (moduli) poi i padri per non dipendere dall'ordine del
    // cascade; whereIn copre entrambi.
    Product::withTrashed()->whereIn('category_2_id', $collectionIds)->forceDelete();
    Category2::withTrashed()->whereIn('id', $collectionIds)->forceDelete();
}

