/**
 * Gli strip vanno applicati **in loop fino a stabilità**, non in una sola
 * passata: l'ordine dei suffissi nella stringa varia da riga a riga (es.
 * "Grand .23 - R", numero-poi-lettera, si riduce a "grand" al primo giro;
 * "Orion - L .24", lettera-poi-numero, richiede due giri — il dash-lettera
 * non fa match nel primo perché la stringa finisce ancora in ".24").
 */
private function normCollezione(string $v): string
{
    $v = mb_strtolower(trim($v));
    $v = (string) preg_replace('/\s+/u', ' ', $v);

    do {
        $before = $v;
        $v = (string) preg_replace('/\s+[cs]\/b$/u', '', $v); // es. "Diva C/B" / "Beverly S/B" (braccioli)
        $v = (string) preg_replace('/\s*-\s*[a-z]$/u', '', $v);
        $v = (string) preg_replace('/\s+(s|m|l|xl|plus l|plus xl)$/u', '', $v);
        $v = (string) preg_replace('/\s*-\s*$/u', '', $v); // dash residuo (es. "office - xl" dopo strip taglia)
        $v = (string) preg_replace('/\s+\.\d+$/u', '', $v);
        $v = (string) preg_replace('/\s+\.[a-z]$/u', '', $v); // es. "Diesis .A/.B/.C"
        $v = (string) preg_replace('/\s+d\d+$/u', '', $v); // es. "Toulouse D60"
        $v = (string) preg_replace('/\s+p\.\d+$/u', '', $v); // es. "Dafne P.80"
        $v = (string) preg_replace('/\s+wall$/u', '', $v); // es. "Adone Wall"
        $v = (string) preg_replace('/\s+office$/u', '', $v); // es. "Diva office"
        $v = trim($v);
    } while ($v !== $before);

    return $v;
}

