// Codice puntato residuo nella collezione v1 (es. "Grand .23 - R" vs
// "Grand - R"): quando il gruppo mischia varianti "base" e varianti
// con questo codice, restringe ai soli candidati coerenti con la
// specifica del prodotto — altrimenti l'euristica forma sotto prende
// il primo match e confonde le due coppie (bug reale: "Tavolo basso
// .23 Q/R" di Grand risultava identico a "Tavolo basso Q/R").
if (preg_match('/\.\d+/', implode(' ', array_column($candidates, 'collezione_raw'))) === 1) {
    preg_match('/\.\d+/', $specifica, $mCode);
    $wantedCode = $mCode[0] ?? null;
    $filtered = array_values(array_filter(
        $candidates,
        function (array $c) use ($wantedCode): bool {
            $hasCode = preg_match('/\.\d+/', $c['collezione_raw'], $m) === 1;

            return $wantedCode !== null ? ($hasCode && $m[0] === $wantedCode) : ! $hasCode;
        },
    ));
    if ($filtered !== [] && count($filtered) < count($candidates)) {
        $candidates = $filtered;
    }
}

