3	declare(strict_types=1);
4	
5	namespace App\Filament\Resources\Materials\Actions;
6	
7	use App\Models\Material;
8	use AtrioTeam\DigitalHub\Tags\Models\Tag;
9	use Filament\Actions\Action;
10	use Filament\Support\Icons\Heroicon;
11	use Illuminate\Support\Facades\Response;
12	use OpenSpout\Common\Entity\Row;
13	use OpenSpout\Writer\XLSX\Writer;
14	use Symfony\Component\HttpFoundation\StreamedResponse;
15	
16	/**
17	 * Esporta l'intera anagrafica materiali (tutte le categorie, non solo quella
18	 * della pagina nidificata da cui si lancia) in XLSX — per far rivedere al
19	 * cliente la trascrizione dal catalogo PDF (nessun file materiali è mai stato
20	 * consegnato, vedi .docs/stato-import.md).
21	 */
22	class ExportMaterialsAction
23	{
24	    public static function make(string $name = 'export'): Action
25	    {
26	        return Action::make($name)
27	            ->label(__('material.export.label'))
28	            ->icon(Heroicon::OutlinedArrowDownTray)
29	            ->action(fn (): StreamedResponse => self::export());
30	    }
31	
32	    private static function export(): StreamedResponse
33	    {
34	        $materials = Material::query()
35	            ->with(['category', 'tags.category'])
36	            ->orderBy('material_category_id')
37	            ->orderBy('sort')
38	            ->get();
39	
40	        $tmpPath = tempnam(sys_get_temp_dir(), 'export-materiali-');
41	        if ($tmpPath === false) {
42	            throw new \RuntimeException('Impossibile creare il file temporaneo per l\'export.');
43	        }
44	
45	        $writer = new Writer();
46	        $writer->openToFile($tmpPath);
47	        $writer->addRow(Row::fromValues([
48	            __('material.export.columns.category'),
49	            __('material.export.columns.name'),
50	            __('material.export.columns.slug'),
51	            __('material.export.columns.finish'),
52	        ]));
53	
54	        foreach ($materials as $material) {
55	            $writer->addRow(Row::fromValues([
56	                self::displayString($material->category?->getTranslation('name', 'it')),
57	                self::displayString($material->getTranslation('name', 'it')),
58	                self::displayString($material->slug),
59	                self::finish($material),
60	            ]));
61	        }
62	
63	        $writer->close();
64	
65	        $filename = 'materiali-' . now()->format('Y-m-d') . '.xlsx';
66	
67	        return Response::streamDownload(function () use ($tmpPath): void {
68	            readfile($tmpPath);
69	            unlink($tmpPath);
70	        }, $filename, [
71	            'Content-Type' => 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
72	        ]);
73	    }
74	
75	    private static function finish(Material $material): string
76	    {
77	        /** @var \Illuminate\Support\Collection<int, Tag> $tags */
78	        $tags = $material->tags;
79	
80	        return $tags
81	            ->filter(fn (Tag $tag): bool => $tag->category?->getTranslation('name', 'it') === 'Finitura')
82	            ->map(fn (Tag $tag): string => self::displayString($tag->getTranslation('name', 'it')))
83	            ->implode(', ');
84	    }
85	
86	    /**
87	     * Stringifica un valore mixed (proveniente da colonne JSON/translatable)
88	     * in modo tipabile per PHPStan: solo gli scalari sono castati, il resto
89	     * diventa stringa vuota.
90	     */
91	    private static function displayString(mixed $value): string
92	    {
93	        if (is_string($value)) {
94	            return $value;
95	        }
96	
97	        return is_scalar($value) ? (string) $value : '';
98	    }
99	}
