/**
 * Tag del blocco dato (Tipologia/Finitura/Colore) dentro il gruppo
 * "Filtri Materiali Interior" (v. ImportFiltriMateriali), comma-separated
 * nella stessa cella.
 */
private static function tagsForBlock(Material $material, string $blockName): string
{
    /** @var \Illuminate\Support\Collection<int, Tag> $tags */
    $tags = $material->tags;

    return $tags
        ->filter(function (Tag $tag) use ($blockName): bool {
            $category = $tag->category;

            return $category?->group?->getTranslation('name', 'it') === 'Filtri Materiali Interior'
                && $category->getTranslation('name', 'it') === $blockName;
        })
        ->map(fn (Tag $tag): string => self::displayString($tag->getTranslation('name', 'it')))
        ->implode(', ');
}

